export function translateItineraryData<T>(value: T, locale: ItineraryLocale): T {
	if (locale === "es") return value;

	const translate = (entry: unknown): unknown => {
		if (typeof entry === "string") {
			return translations[locale][entry] ?? additionalTranslations[entry]?.[locale] ?? entry;
		}
		if (Array.isArray(entry)) return entry.map(translate);
		if (entry && typeof entry === "object") {
			return Object.fromEntries(
				Object.entries(entry).map(([key, nestedValue]) => [key, translate(nestedValue)]),
			);
		}
		return entry;
	};

	return translate(value) as T;
}
